<?php
require_once __DIR__.'/school_offerings.php';
require_once __DIR__.'/catalog_validation.php';
$offeringAdmin=$offeringAdmin??false;
$school_id=(int)$school_id;$canSelect=$offeringAdmin||Auth::getRole()==='school_admin';
$filter_class=(int)($_GET['class']??$_GET['class_id']??0);$error='';$success='';
$schoolRow=$db->prepare('SELECT name_en FROM schools WHERE id=?');$schoolRow->execute([$school_id]);$schoolName=$schoolRow->fetchColumn();if(!$schoolName)denySchoolRequest('School not found.',404);
if($filter_class)try{schoolRecord($db,'classes',$filter_class,$school_id);}catch(InvalidArgumentException $e){denySchoolRequest($e->getMessage(),404);}
if($_SERVER['REQUEST_METHOD']==='POST')try{
    if(!$canSelect)denySchoolRequest('Only the school administrator may select teaching subjects.');
    foreach(['name_en','name_np','code','is_optional','credit_hours','th_credit_hours','in_credit_hours','th_full_marks','th_pass_marks','in_full_marks','in_pass_marks'] as $protectedField)if(array_key_exists($protectedField,$_POST))throw new InvalidArgumentException('Catalog definitions cannot be edited from school assignments.');
    foreach(['offering_class','offering_subject'] as $idField)if(isset($_POST[$idField])&&(!is_scalar($_POST[$idField])||!preg_match('/^[1-9][0-9]*$/',(string)$_POST[$idField])))throw new InvalidArgumentException('Choose a valid school class and subject.');
    $action=$_POST['offering_action']??'';if(!is_string($action))throw new InvalidArgumentException('Choose a valid offering action.');
    if($offeringAdmin&&$action==='synchronize'){
        $db->beginTransaction();catalogWriteLock($db,0);syncSchoolOfferings($db,$school_id);$db->commit();
        Auth::logActivity(Auth::getUserId(),'Synchronize school catalog','schools',$school_id);$success='Catalog synchronized. Existing school selections and exceptions were retained.';
    }elseif($offeringAdmin&&in_array($action,['hide_class','show_class'],true)){
        $classId=(int)($_POST['offering_class']??0);$c=schoolRecord($db,'classes',$classId,$school_id);
        $db->beginTransaction();catalogWriteLock($db,0);catalogWriteLock($db,$school_id);
        offeringStoreState($db,$school_id,$classId,0,$action==='hide_class'?'blocked':null);
        if($action==='show_class'&&!empty($c['source_id'])&&!schoolRecord($db,'classes',(int)$c['source_id'],0)['is_active'])throw new InvalidArgumentException('Enable the universal class before showing it for this school.');
        $db->prepare('UPDATE classes SET is_active=? WHERE id=? AND school_id=?')->execute([$action==='show_class'?1:0,$classId,$school_id]);$db->commit();
        Auth::logActivity(Auth::getUserId(),'School offering '.$action,'classes',$classId);$success='School class visibility saved. Linked records are retained.';
    }else{
        saveSchoolOffering($db,$school_id,(int)Auth::getUserId(),Auth::getRole(),(int)($_POST['offering_class']??0),(int)($_POST['offering_subject']??0),$action,$_POST);
        $success='School teaching assignment saved. Historical exam and result records were retained.';
    }
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e instanceof InvalidArgumentException?$e->getMessage():schoolPublicError($e);}
$q=$db->prepare('SELECT * FROM classes WHERE school_id=?'.($offeringAdmin?'':' AND is_active=1').' ORDER BY id');$q->execute([$school_id]);$all_classes_filter=$q->fetchAll();
$q=$db->prepare('SELECT s.*,c.source_id class_source_id,c.name class_name,c.id class_id,c.is_active class_active,CASE WHEN '.schoolSubjectAssignedSql('s.school_id','c.id','s.id').' THEN 1 ELSE 0 END assigned,cs.teacher_id teacher_ids,cs.id mapping_id,cs.is_optional,cs.is_active,cs.section_id,cs.weekly_periods,CASE WHEN cs.id IS NULL THEN s.th_credit_hours ELSE cs.th_credit_hours END th_credit_hours,CASE WHEN cs.id IS NULL THEN s.in_credit_hours ELSE cs.in_credit_hours END in_credit_hours,CASE WHEN cs.id IS NULL THEN s.th_full_marks ELSE cs.th_full_marks END th_full_marks,CASE WHEN cs.id IS NULL THEN s.th_pass_marks ELSE cs.th_pass_marks END th_pass_marks,CASE WHEN cs.id IS NULL THEN s.in_full_marks ELSE cs.in_full_marks END in_full_marks,CASE WHEN cs.id IS NULL THEN s.in_pass_marks ELSE cs.in_pass_marks END in_pass_marks FROM subjects s LEFT JOIN class_subjects cs ON cs.subject_id=s.id AND cs.school_id=s.school_id LEFT JOIN classes c ON c.id=cs.class_id AND c.school_id=s.school_id WHERE s.school_id=?'.($filter_class?' AND cs.class_id=?':'').' ORDER BY c.id,s.name_en,s.id');$q->execute([$school_id,...($filter_class?[$filter_class]:[])]);$rows=$q->fetchAll();
$stateQuery=$db->prepare('SELECT meta_key,meta_value FROM app_meta WHERE meta_key LIKE ? OR meta_key LIKE ?');$stateQuery->execute(['school_offering:'.$school_id.':%','catalog_mapping:'.$school_id.':%']);$states=$stateQuery->fetchAll(PDO::FETCH_KEY_PAIR);
$defaults=$db->query("SELECT meta_key,meta_value FROM app_meta WHERE meta_key LIKE 'catalog_required:%'")->fetchAll(PDO::FETCH_KEY_PAIR);$required=[];$requiredById=[];foreach($db->query('SELECT id,class_id,subject_id,is_optional FROM class_subjects WHERE school_id=0') as $m){$key=$m['class_id'].'/'.$m['subject_id'];$setting=$defaults['catalog_required:'.$m['class_id'].':'.$m['subject_id']]??null;$required[$key]=$setting===null?empty($m['is_optional']):$setting==='1';$requiredById[$m['id']]=$required[$key];}
$subjects=[];foreach($rows as $r){$sourceLink=$states['catalog_mapping:'.$school_id.':'.$r['class_id'].':'.$r['id']]??0;$r['required']=$requiredById[$sourceLink]??($required[($r['class_source_id']??0).'/'.($r['source_id']??0)]??empty($r['is_optional']));$r['blocked']=($states[offeringStateKey($school_id,(int)$r['class_id'],(int)$r['id'])]??null)==='blocked';if(!$canSelect&&!$r['assigned'])continue;if(!$offeringAdmin&&$r['class_id']&&!$r['class_active'])continue;$subjects[]=$r;}
usort($subjects,static fn($a,$b)=>(int)$b['assigned']<=>(int)$a['assigned']?:((int)$a['class_id']<=>(int)$b['class_id']?:strcasecmp($a['name_en'],$b['name_en'])));
$q=$db->prepare("SELECT id,full_name FROM users WHERE school_id=? AND role='teacher' AND status=1 ORDER BY full_name");$q->execute([$school_id]);$all_teachers=$q->fetchAll(PDO::FETCH_KEY_PAIR);
$q=$db->prepare('SELECT id,class_id,name FROM sections WHERE school_id=? ORDER BY name');$q->execute([$school_id]);$sections=$q->fetchAll();
$pageTitle='School teaching subjects';$activePage=$offeringAdmin?'super_admin_schools':'subjects';$pageId='subjects-index';
ob_start(); ?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><h2>School teaching subjects</h2><p class="text-muted mb-0"><?= sanitize($schoolName) ?> · Assigned subjects appear first. Catalog names, codes, marks and compulsory defaults are managed by system admin.</p></div><?php if($offeringAdmin): ?><a class="btn btn-outline-secondary" href="<?= schoolRouteUrl('modules/super_admin/schools.php') ?>">Schools</a><?php endif; ?></div>
<?php if($error): ?><div class="alert alert-danger" role="alert"><?= sanitize($error) ?></div><?php endif; ?><?php if($success): ?><div class="alert alert-success" role="status"><?= sanitize($success) ?></div><?php endif; ?>
<div class="alert alert-info">Compulsory subjects are assigned to every school by system admin. School admins can select additional offered subjects and their teachers. Request a system-admin exception to hide a compulsory subject for this school. Removing an offering affects current teaching, question banks and future exams; saved results retain their exam snapshot.</div>
<form method="GET" class="d-flex gap-2 mb-3 align-items-end"><?php if($offeringAdmin): ?><input type="hidden" name="school_id" value="<?= $school_id ?>"><?php endif; ?><div><label class="form-label" for="filter_class">Class</label><select class="form-select" id="filter_class" name="class"><option value="">All classes</option><?php foreach($all_classes_filter as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $filter_class===(int)$c['id']?'selected':'' ?>><?= sanitize($c['name']) ?><?= !$c['is_active']?' (hidden)':'' ?></option><?php endforeach; ?></select></div><button class="btn btn-primary">View</button></form>
<?php if($offeringAdmin): ?><form method="POST" class="mb-3"><input type="hidden" name="offering_action" value="synchronize"><button class="btn btn-outline-primary">Synchronize latest admin catalog</button></form><details class="card card-body mb-3"><summary>Classes available to this school</summary><div class="row g-2 mt-2"><?php foreach($all_classes_filter as $c): ?><form method="POST" class="col-md-4"><input type="hidden" name="offering_action" value="<?= $c['is_active']?'hide_class':'show_class' ?>"><input type="hidden" name="offering_class" value="<?= $c['id'] ?>"><span><?= sanitize($c['name']) ?></span> <button class="btn btn-sm btn-outline-secondary"><?= $c['is_active']?'Hide for this school':'Show for this school' ?></button></form><?php endforeach; ?></div></details><?php endif; ?>
<label class="form-label" for="filter_subject">Search subjects</label><input class="form-control mb-3" id="filter_subject" type="search" placeholder="Subject name or code">
<div class="card"><div class="card-header">Assigned first · <?= count(array_filter($subjects,static fn($s)=>$s['assigned'])) ?> teaching subjects</div><div class="table-responsive"><table class="table align-middle" id="subjectTable"><thead><tr><th>Code</th><th>Subject</th><th>Class</th><th>Teachers</th><th>Credit TH / IN</th><th>Marks TH / IN</th><th>School offering</th><?php if($canSelect): ?><th>Actions</th><?php endif; ?></tr></thead><tbody>
<?php foreach($subjects as $s): ?><tr data-school-assigned="<?= $s['assigned']?'1':'0' ?>"><td><?= sanitize($s['code']??'—') ?></td><td><strong><?= sanitize($s['name_en']) ?></strong><br><small><?= sanitize($s['name_np']??'') ?></small></td><td><?= sanitize($s['class_name']??'No catalog class mapping') ?></td><td><?php $names=[];foreach(explode(',',(string)$s['teacher_ids']) as $tid)if(isset($all_teachers[$tid]))$names[]=sanitize($all_teachers[$tid]);echo implode(', ',$names)?:'—'; ?></td><td><?= sanitize($s['th_credit_hours']??'—') ?> / <?= sanitize($s['in_credit_hours']??'—') ?></td><td><?= sanitize($s['th_full_marks']??'—') ?> / <?= sanitize($s['in_full_marks']??'—') ?></td><td><span class="badge <?= $s['assigned']?'bg-success':'bg-secondary' ?>"><?= $s['assigned']?'Assigned':($s['blocked']?'Hidden by system admin':'Not assigned') ?></span><br><small><?= $s['mapping_id']&&$s['required']?'Compulsory for all schools':'School choice' ?></small></td>
<?php if($canSelect): ?><td><?php if($s['mapping_id']): ?>
<?php if($offeringAdmin||(!$s['blocked']&&!$s['required']&&empty($s['is_hidden']))): ?><form method="POST" class="mb-2"><input type="hidden" name="offering_class" value="<?= $s['class_id'] ?>"><input type="hidden" name="offering_subject" value="<?= $s['id'] ?>"><input type="hidden" name="offering_action" value="<?= $offeringAdmin?($s['assigned']?'block':'restore'):($s['assigned']?'unassign':'assign') ?>"><button class="btn btn-sm <?= $s['assigned']?'btn-outline-secondary':'btn-outline-primary' ?>"><?= $s['assigned']?($offeringAdmin?'Hide for this school':'Unassign'):($offeringAdmin?'Allow for this school':'Assign to teach') ?></button></form><?php endif; ?>
<?php if($s['assigned']): ?><details><summary>Assign teachers</summary><form method="POST" class="mt-2"><input type="hidden" name="offering_action" value="teachers"><input type="hidden" name="offering_mapping" value="<?= $s['mapping_id'] ?>"><input type="hidden" name="offering_class" value="<?= $s['class_id'] ?>"><input type="hidden" name="offering_subject" value="<?= $s['id'] ?>"><label>Teachers<select class="form-select" name="teacher_ids[]" multiple><?php foreach($all_teachers as $tid=>$name): ?><option value="<?= $tid ?>" <?= in_array((string)$tid,explode(',',(string)$s['teacher_ids']),true)?'selected':'' ?>><?= sanitize($name) ?></option><?php endforeach; ?></select></label><label>Section<select class="form-select" name="section_id"><option value="">All sections</option><?php foreach($sections as $sec):if($sec['class_id']!=$s['class_id'])continue; ?><option value="<?= $sec['id'] ?>" <?= $sec['id']==$s['section_id']?'selected':'' ?>><?= sanitize($sec['name']) ?></option><?php endforeach; ?></select></label><label>Weekly periods<input class="form-control" name="weekly_periods" type="number" min="0" max="50" value="<?= sanitize($s['weekly_periods']??'') ?>"></label><button class="btn btn-sm btn-primary mt-2">Save teachers</button></form></details><?php endif; ?>
<?php endif; ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div></div>
<?php $content=ob_get_clean();require __DIR__.'/header.php';
